class UploadService : Service() {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    override fun onCreate() {
        super.onCreate()
        createUploadChannel()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        startForeground(NOTIFICATION_ID, buildNotification(progress = 0))
        val uploadId = intent?.getStringExtra(EXTRA_UPLOAD_ID)
            ?: return START_NOT_STICKY.also { stopSelf(startId) }
        scope.launch {
            runCatching { repository.resumeUpload(uploadId) }
            stopSelfResult(startId)
        }
        return START_NOT_STICKY
    }

    override fun onDestroy() {
        scope.cancel()
        super.onDestroy()
    }

    override fun onBind(intent: Intent?): IBinder? = null
}

suspend fun startUpload(context: Context, uploadId: String) {
    repository.markQueued(uploadId)
    ContextCompat.startForegroundService(
        context,
        Intent(context, UploadService::class.java)
            .setAction(ACTION_START)
            .putExtra(EXTRA_UPLOAD_ID, uploadId)
    )
}

private fun cancelPendingIntent(context: Context, uploadId: String): PendingIntent {
    val intent = Intent(context, UploadService::class.java)
        .setAction(ACTION_CANCEL)
        .putExtra(EXTRA_UPLOAD_ID, uploadId)
    return PendingIntent.getService(
        context,
        uploadId.hashCode(),
        intent,
        PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
    )
}

private fun finishService(startId: Int) {
    stopForeground(STOP_FOREGROUND_REMOVE)
    stopSelfResult(startId)
}

override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
    when (intent?.action) {
        ACTION_CANCEL -> repository.cancel(intent.requireUploadId())
        ACTION_START -> launchUploadOnce(intent.requireUploadId(), startId)
        else -> stopSelf(startId)
    }
    return START_NOT_STICKY
}
